export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;

    const corsHeaders = {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, X-Auth-Token'
    };

    if (request.method === 'OPTIONS') {
      return new Response(null, { headers: corsHeaders });
    }

    // Operator Console
    if (path === '/entry') {
      return new Response(ENTRY_HTML, {
        headers: { 'Content-Type': 'text/html; charset=utf-8' }
      });
    }

    // Master API
    if (path === '/api/all_candidates_master') {
      return new Response(JSON.stringify(MASTER_DATA), {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      });
    }

    // Auth Login
    if (path === '/api/auth/login' && request.method === 'POST') {
      try {
        const body = await request.json();
        const pwd = (body.password || '').trim();
        if (pwd === 'salumber2026' || pwd === 'admin2026') {
          return new Response(JSON.stringify({
            status: 'success',
            token: 'salumber_cf_token_2026',
            message: 'Authenticated successfully!'
          }), {
            headers: { ...corsHeaders, 'Content-Type': 'application/json' }
          });
        } else {
          return new Response(JSON.stringify({ detail: 'Invalid password!' }), {
            status: 401,
            headers: { ...corsHeaders, 'Content-Type': 'application/json' }
          });
        }
      } catch (e) {
        return new Response(JSON.stringify({ detail: 'Bad request' }), { status: 400, headers: corsHeaders });
      }
    }

    if (path === '/api/auth/check') {
      const token = request.headers.get('X-Auth-Token');
      return new Response(JSON.stringify({
        authenticated: token === 'salumber_cf_token_2026'
      }), {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      });
    }

    if (path === '/api/ward_configs') {
      return new Response(JSON.stringify({
        status: 'success',
        wards: MASTER_DATA.wards
      }), {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' }
      });
    }

    if (path === '/api/save_votes' && request.method === 'POST') {
      try {
        const payload = await request.json();
        const votes = payload.votes || {};
        const rKey = payload.round_key;
        for (const [cid, count] of Object.entries(votes)) {
          if (!MASTER_DATA.roundVotes[cid]) MASTER_DATA.roundVotes[cid] = {};
          MASTER_DATA.roundVotes[cid][rKey] = count;
        }
        return new Response(JSON.stringify({ status: 'success', message: 'Votes saved successfully' }), {
          headers: { ...corsHeaders, 'Content-Type': 'application/json' }
        });
      } catch(e) {
        return new Response(JSON.stringify({ detail: e.message }), { status: 500, headers: corsHeaders });
      }
    }

    // Default Route: Public TV Display Screen (/)
    return new Response(INDEX_HTML, {
      headers: { 'Content-Type': 'text/html; charset=utf-8' }
    });
  }
};
